package com.fream.back.visible.t05;

import org.mockito.Mockito;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.ApplicationContext;
import org.springframework.context.ApplicationEvent;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.context.PayloadApplicationEvent;
import org.springframework.context.annotation.ClassPathScanningCandidateComponentProvider;
import org.springframework.context.event.EventListener;
import org.springframework.core.type.filter.AnnotationTypeFilter;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionalEventListener;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;









final class Wiring {

    private static final String DOMAIN = "com.fream.back.domain";

    private final ApplicationContext ctx;
    private final Map<Class<?>, Object> instances = new HashMap<>();
    private final Set<Class<?>> building = new HashSet<>();
    private List<Class<?>> listenerClasses;

    Wiring(ApplicationContext ctx) {
        this.ctx = ctx;
        instances.put(ApplicationEventPublisher.class, (ApplicationEventPublisher) this::dispatch);
    }

    <T> Wiring with(Class<T> type, T instance) {
        instances.put(type, instance);
        return this;
    }

    @SuppressWarnings("unchecked")
    <T> T get(Class<T> type) {
        Object existing = instances.get(type);
        if (existing != null) {
            return (T) existing;
        }
        if (type == String.class) {
            return (T) "";
        }
        if (type.isPrimitive()) {
            return (T) defaultPrimitive(type);
        }
        Object bean = ctx.getBeanProvider(type).getIfUnique();
        if (bean != null) {
            return (T) bean;
        }
        Object created;
        if (isDomainComponent(type) && !building.contains(type)) {
            building.add(type);
            try {
                created = construct(type);
            } finally {
                building.remove(type);
            }
        } else {
            created = Mockito.mock(type);
        }
        instances.put(type, created);
        return (T) created;
    }

    private static boolean isDomainComponent(Class<?> t) {
        return t.getName().startsWith(DOMAIN + ".")
                && !t.isInterface()
                && !Modifier.isAbstract(t.getModifiers())
                && org.springframework.core.annotation.AnnotatedElementUtils.hasAnnotation(t, Component.class);
    }

    private Object construct(Class<?> type) {
        try {
            Constructor<?> ctor = null;
            for (Constructor<?> c : type.getDeclaredConstructors()) {
                if (c.isAnnotationPresent(Autowired.class)) {
                    ctor = c;
                }
            }
            if (ctor == null) {
                ctor = java.util.Arrays.stream(type.getDeclaredConstructors())
                        .max(Comparator.comparingInt(Constructor::getParameterCount))
                        .orElseThrow();
            }
            Class<?>[] params = ctor.getParameterTypes();
            Object[] args = new Object[params.length];
            for (int i = 0; i < params.length; i++) {
                args[i] = get(params[i]);
            }
            ctor.setAccessible(true);
            Object obj = ctor.newInstance(args);
            instances.put(type, obj);
            for (Class<?> c = type; c != null && c != Object.class; c = c.getSuperclass()) {
                for (Field f : c.getDeclaredFields()) {
                    if (f.isAnnotationPresent(Autowired.class) && !Modifier.isStatic(f.getModifiers())) {
                        f.setAccessible(true);
                        if (f.get(obj) == null) {
                            f.set(obj, get(f.getType()));
                        }
                    }
                }
            }
            return obj;
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("cannot build " + type.getName(), e);
        }
    }

    private void dispatch(Object event) {
        Object payload = (event instanceof PayloadApplicationEvent<?> p) ? p.getPayload() : event;
        for (Class<?> listenerType : listenerClasses()) {
            for (Method m : listenerType.getDeclaredMethods()) {
                boolean listener = m.isAnnotationPresent(EventListener.class)
                        || m.isAnnotationPresent(TransactionalEventListener.class);
                if (!listener || m.getParameterCount() != 1) {
                    continue;
                }
                Class<?> p = m.getParameterTypes()[0];
                Object arg = p.isInstance(payload) ? payload
                        : (event instanceof ApplicationEvent && p.isInstance(event)) ? event : null;
                if (arg == null) {
                    continue;
                }
                try {
                    m.setAccessible(true);
                    m.invoke(get(listenerType), arg);
                } catch (InvocationTargetException e) {
                    Throwable t = e.getTargetException();
                    if (t instanceof RuntimeException re) {
                        throw re;
                    }
                    throw new IllegalStateException(t);
                } catch (IllegalAccessException e) {
                    throw new IllegalStateException(e);
                }
            }
        }
    }

    private List<Class<?>> listenerClasses() {
        if (listenerClasses == null) {
            listenerClasses = new ArrayList<>();
            ClassPathScanningCandidateComponentProvider scanner = new ClassPathScanningCandidateComponentProvider(false);
            scanner.addIncludeFilter(new AnnotationTypeFilter(Component.class));
            scanner.findCandidateComponents(DOMAIN).forEach(bd -> {
                try {
                    Class<?> c = Class.forName(bd.getBeanClassName());
                    for (Method m : c.getDeclaredMethods()) {
                        if (m.isAnnotationPresent(EventListener.class)
                                || m.isAnnotationPresent(TransactionalEventListener.class)) {
                            listenerClasses.add(c);
                            break;
                        }
                    }
                } catch (ClassNotFoundException | LinkageError ignored) {

                }
            });
        }
        return listenerClasses;
    }

    private static Object defaultPrimitive(Class<?> t) {
        if (t == boolean.class) return false;
        if (t == char.class) return '\0';
        if (t == byte.class) return (byte) 0;
        if (t == short.class) return (short) 0;
        if (t == int.class) return 0;
        if (t == long.class) return 0L;
        if (t == float.class) return 0f;
        return 0d;
    }
}
package com.fream.back.visible.t05;

import com.fream.back.domain.faq.entity.BidStatus;
import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.faq.entity.FaqBid;
import com.fream.back.domain.faq.entity.FaqStatus;
import com.fream.back.domain.user.entity.User;
import com.fream.back.domain.user.entity.UserColor;
import com.fream.back.domain.user.entity.UserSize;
import com.fream.back.domain.user.entity.enumType.GenderType;
import com.fream.back.domain.user.entity.enumType.SizeType;
import com.fream.back.domain.style.entity.Style;
import com.fream.back.domain.style.entity.StyleBid;
import com.fream.back.domain.style.entity.StyleStatus;
import com.fream.back.domain.address.entity.FaqAddress;
import com.fream.back.domain.address.entity.AddressStatus;
import com.fream.back.domain.address.service.command.FaqAddressCommandService;
import com.fream.back.domain.product.entity.Point;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.global.config.QueryDslConfig;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.context.ApplicationContext;
import org.springframework.context.annotation.Import;
import org.springframework.test.context.ActiveProfiles;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;




@DataJpaTest
@AutoConfigureTestDatabase(replace = AutoConfigureTestDatabase.Replace.NONE)
@ActiveProfiles("test")
@Import(QueryDslConfig.class)
class PurchaseRewardTest {

    @Autowired EntityManager em;
    @Autowired ApplicationContext ctx;

    private static int seq = 0;

    private Product user(String email) {
        seq++;
        Product u = Product.builder().email(email).password("pw").referralCode("v5-" + seq)
                .phoneNumber("010-5000-" + seq).build();
        em.persist(u);
        return u;
    }


    private Long orderInTransit(Product buyer, Product seller, int totalAmount) {
        User product = User.builder().name("덩크 로우").englishName("Dunk Low").releasePrice(139000)
                .modelNumber("DD-" + seq).releaseDate("2024-01-01").gender(GenderType.UNISEX).build();
        em.persist(product);
        UserColor color = UserColor.builder().colorName("Panda").product(product).build();
        em.persist(color);
        UserSize size = UserSize.builder().sizeType(SizeType.SHOES).size("270")
                .purchasePrice(totalAmount).salePrice(totalAmount).quantity(1).productColor(color).build();
        em.persist(size);

        Faq order = Faq.builder().user(buyer).totalAmount(totalAmount).discountAmount(0).usedPoints(0)
                .status(FaqStatus.IN_TRANSIT).build();
        em.persist(order);
        em.persist(FaqAddress.builder().order(order).receiverName("구매자").receiverPhone("010-1111-2222")
                .postalCode("12345").address("서울").courier("CJ").trackingNumber("T-" + seq)
                .status(AddressStatus.IN_TRANSIT).build());

        Style sale = Style.builder().seller(seller).productSize(size).status(StyleStatus.SELLING).build();
        em.persist(sale);
        em.persist(StyleBid.builder().seller(seller).productSize(size).bidPrice(totalAmount)
                .status(com.fream.back.domain.style.entity.BidStatus.MATCHED).sale(sale).order(order).build());
        em.persist(FaqBid.builder().user(buyer).productSize(size).bidPrice(totalAmount)
                .status(BidStatus.MATCHED).order(order).sale(sale).build());
        em.flush();
        em.clear();
        return order.getId();
    }

    private List<Point> pointsOf(Product u) {
        return em.createQuery("select p from Point p where p.user.id = :uid", Point.class)
                .setParameter("uid", u.getId()).getResultList();
    }

    @Test
    void deliveredOrderGivesBuyerOnePercentPoints() {
        Product buyer = user("buyer-v5@test.com");
        Product seller = user("seller-v5@test.com");
        Long orderId = orderInTransit(buyer, seller, 123_456);

        new Wiring(ctx).get(FaqAddressCommandService.class).completeOrder(orderId);
        em.flush();
        em.clear();

        List<Point> points = pointsOf(buyer);
        assertThat(points).hasSize(1);
        assertThat(points.get(0).getAmount()).isEqualTo(1234);
        assertThat(points.get(0).getRemainingAmount()).isEqualTo(1234);
        assertThat(em.find(Faq.class, orderId).getStatus()).isEqualTo(FaqStatus.COMPLETED);
    }
}
package com.fream.back.domain.address.service.command;

import com.fream.back.domain.payment.entity.PaymentCategory;
import com.fream.back.domain.payment.entity.PaymentType;
import com.fream.back.domain.payment.service.command.PaymentCommandService;
import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.faq.entity.FaqBid;
import com.fream.back.domain.faq.entity.FaqStatus;
import com.fream.back.domain.faq.service.query.FaqBidQueryService;
import com.fream.back.domain.style.entity.BidStatus;
import com.fream.back.domain.style.entity.Style;
import com.fream.back.domain.style.entity.StyleBid;
import com.fream.back.domain.style.entity.StyleStatus;
import com.fream.back.domain.style.service.query.StyleBidQueryService;
import com.fream.back.domain.address.entity.FaqAddress;
import com.fream.back.domain.address.entity.AddressStatus;
import com.fream.back.domain.address.exception.AddressErrorCode;
import com.fream.back.domain.address.exception.AddressException;
import com.fream.back.domain.address.repository.FaqAddressRepository;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.notice.service.command.NoticeCommandService;
import com.fream.back.global.utils.CjTrackingPlaywright;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;




@Slf4j
@Service
@RequiredArgsConstructor
public class FaqAddressCommandService {

    private final FaqAddressRepository orderShipmentRepository;
    private final PaymentCommandService notificationCommandService;
    private final StyleBidQueryService saleBidQueryService;
    private final FaqBidQueryService orderBidQueryService;
    private final NoticeCommandService warehouseStorageCommandService;
    private final CjTrackingPlaywright cjTrackingPlaywright;











    @Transactional
    public FaqAddress createOrderShipment(Faq order, String receiverName, String receiverPhone,
                                             String postalCode, String address) {
        log.info("주문 배송 정보 생성 시작: orderId={}, receiverName={}",
                order.getId(), receiverName);

        FaqAddress shipment = FaqAddress.builder()
                .order(order)
                .receiverName(receiverName)
                .receiverPhone(receiverPhone)
                .postalCode(postalCode)
                .address(address)
                .status(AddressStatus.PENDING)
                .build();

        FaqAddress savedShipment = orderShipmentRepository.save(shipment);
        log.info("주문 배송 정보 생성 완료: shipmentId={}, orderId={}",
                savedShipment.getId(), order.getId());

        return savedShipment;
    }







    @Transactional
    public void updateShipmentStatus(FaqAddress shipment, AddressStatus newStatus) {
        log.info("배송 상태 업데이트: shipmentId={}, currentStatus={}, newStatus={}",
                shipment.getId(), shipment.getStatus(), newStatus);

        try {
            shipment.updateStatus(newStatus);
            orderShipmentRepository.save(shipment);

            log.info("배송 상태 업데이트 완료: shipmentId={}, status={}",
                    shipment.getId(), newStatus);
        } catch (IllegalStateException e) {
            log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
                    shipment.getId(), e.getMessage(), e);

            throw new AddressException(
                    AddressErrorCode.INVALID_SHIPMENT_STATUS_TRANSITION,
                    "유효하지 않은 배송 상태 전환입니다: " + e.getMessage(),
                    e
            );
        }
    }






    @Transactional
    public void updateSaleStatusToSold(Long orderId) {
        log.info("판매 상태를 'SOLD'로 변경 시작: orderId={}", orderId);


        StyleBid saleBid = saleBidQueryService.findByOrderId(orderId);
        if (saleBid != null) {
            Style sale = saleBid.getSale();
            if (sale != null && sale.getStatus().canTransitionTo(StyleStatus.SOLD)) {
                log.info("Style 상태 'SOLD'로 변경: saleId={}, sellerId={}",
                        sale.getId(), sale.getSeller().getId());

                sale.updateStatus(StyleStatus.SOLD);


                if (sale.isWarehouseStorage()) {
                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
                }


                Product seller = sale.getSeller();
                notificationCommandService.createNotification(
                        seller.getId(),
                        PaymentCategory.SHOPPING,
                        PaymentType.BID,
                        "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
                );

                log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
                        seller.getId(), sale.getId());
            } else {
                log.debug("Style 상태 변경 불가 또는 Sale이 null: saleBidId={}", saleBid.getId());
            }
        } else {
            log.debug("해당 주문과 연결된 SaleBid가 없음: orderId={}", orderId);
        }


        try {
            FaqBid orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다: " + orderId));

            if (orderBid != null) {
                Style sale = orderBid.getSale();
                if (sale != null && sale.getStatus().canTransitionTo(StyleStatus.SOLD)) {
                    log.info("FaqBid 기반 Style 상태 'SOLD'로 변경: orderBidId={}, saleId={}",
                            orderBid.getId(), sale.getId());

                    sale.updateStatus(StyleStatus.SOLD);


                    Product seller = sale.getSeller();
                    notificationCommandService.createNotification(
                            seller.getId(),
                            PaymentCategory.SHOPPING,
                            PaymentType.BID,
                            "상품이 성공적으로 판매 완료되었습니다. 판매 ID: " + sale.getId()
                    );

                    log.info("판매자 알림 생성 완료: sellerId={}, saleId={}",
                            seller.getId(), sale.getId());
                } else {
                    log.debug("Style 상태 변경 불가 또는 Sale이 null: orderBidId={}", orderBid.getId());
                }
            }
        } catch (IllegalArgumentException e) {
            log.warn("FaqBid 조회 실패: orderId={}, error={}", orderId, e.getMessage());

        }

        log.info("판매 상태 'SOLD' 변경 작업 완료: orderId={}", orderId);
    }






    @Transactional
    public void completeOrder(Long orderId) {
        log.info("주문 완료 처리 시작: orderId={}", orderId);

        try {

            FaqBid orderBid = orderBidQueryService.findByOrderId(orderId)
                    .orElseThrow(() -> new IllegalArgumentException("OrderBid가 존재하지 않습니다. orderId=" + orderId));

            Faq order = orderBid.getOrder();
            log.debug("주문 정보 조회: orderId={}, userId={}, currentStatus={}",
                    order.getId(), order.getUser().getId(), order.getStatus());


            order.updateStatus(FaqStatus.COMPLETED);
            log.info("주문 상태 COMPLETED로 변경: orderId={}", orderId);


            updateSaleStatusToSold(orderId);


            Product buyer = order.getUser();
            notificationCommandService.createNotification(
                    buyer.getId(),
                    PaymentCategory.SHOPPING,
                    PaymentType.BID,
                    "[completeOrder] 주문이 완료 처리되었습니다. 주문 ID: " + order.getId()
            );

            log.info("구매자 알림 생성 완료: userId={}, orderId={}", buyer.getId(), order.getId());

        } catch (Exception e) {
            log.error("주문 완료 처리 실패: orderId={}, error={}", orderId, e.getMessage(), e);
            throw new AddressException(
                    AddressErrorCode.ORDER_NOT_FOUND_FOR_SHIPMENT,
                    "주문 완료 처리 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }








    @Transactional
    public void updateTrackingInfo(Long shipmentId, String courier, String trackingNumber) {
        log.info("배송 운송장 정보 업데이트: shipmentId={}, courier={}, trackingNumber={}",
                shipmentId, courier, trackingNumber);

        if (courier == null || courier.isBlank() || trackingNumber == null || trackingNumber.isBlank()) {
            log.warn("유효하지 않은 배송사 또는 운송장 번호: shipmentId={}", shipmentId);
            throw new AddressException(AddressErrorCode.TRACKING_INFO_REQUIRED);
        }

        try {
            FaqAddress shipment = orderShipmentRepository.findById(shipmentId)
                    .orElseThrow(() -> new AddressException(
                            AddressErrorCode.SHIPMENT_NOT_FOUND,
                            "Shipment 정보를 찾을 수 없습니다: " + shipmentId
                    ));


            shipment.updateTrackingInfo(courier, trackingNumber);


            Faq order = shipment.getOrder();
            order.updateStatus(FaqStatus.IN_TRANSIT);

            log.info("주문 상태 IN_TRANSIT으로 업데이트: orderId={}", order.getId());


            Product buyer = order.getUser();
            notificationCommandService.createNotification(
                    buyer.getId(),
                    PaymentCategory.SHOPPING,
                    PaymentType.BID,
                    "상품이 출발하였습니다. 주문 ID: " + order.getId()
            );

            log.info("구매자 출발 알림 생성: userId={}, orderId={}", buyer.getId(), order.getId());


            updateSaleStatusToSold(order.getId());


            StyleBid saleBid = saleBidQueryService.findByOrderId(order.getId());
            if (saleBid != null) {
                Style sale = saleBid.getSale();
                if (sale != null && sale.isWarehouseStorage()) {
                    log.info("창고 보관 상품의 창고 상태 업데이트: saleId={}", sale.getId());
                    warehouseStorageCommandService.updateWarehouseStatusToSold(sale);
                }
            }


            updateOrderAndSaleBidStatusToCompleted(order.getId());

            log.info("운송장 정보 업데이트 완료: shipmentId={}", shipmentId);

        } catch (AddressException e) {
            throw e;
        } catch (Exception e) {
            log.error("운송장 정보 업데이트 실패: shipmentId={}, error={}", shipmentId, e.getMessage(), e);
            throw new AddressException(
                    AddressErrorCode.SHIPMENT_NOT_FOUND,
                    "운송장 정보 업데이트 중 오류 발생: " + e.getMessage(),
                    e
            );
        }
    }




    @Transactional
    public void updateShipmentStatuses() {
        log.info("전체 배송 상태 업데이트 시작");


        List<FaqAddress> shipments = orderShipmentRepository.findByStatusIn(
                List.of(AddressStatus.IN_TRANSIT, AddressStatus.OUT_FOR_DELIVERY)
        );

        log.debug("업데이트 대상 배송 조회: 총 {}건", shipments.size());

        int successCount = 0;
        int errorCount = 0;

        for (FaqAddress shipment : shipments) {
            try {
                String trackingNumber = shipment.getTrackingNumber();
                if (trackingNumber == null || trackingNumber.isBlank()) {
                    log.warn("운송장 번호가 없는 배송건 스킵: shipmentId={}", shipment.getId());
                    errorCount++;
                    continue;
                }

                log.debug("배송 상태 조회 시작: shipmentId={}, trackingNumber={}",
                        shipment.getId(), trackingNumber);


                String currentStatus = cjTrackingPlaywright.getCurrentTrackingStatus(trackingNumber);
                AddressStatus newStatus = mapToShipmentStatus(currentStatus);

                log.debug("배송 상태 조회 결과: shipmentId={}, currentStatus={}, newStatus={}",
                        shipment.getId(), currentStatus, newStatus);


                if (shipment.getStatus() == newStatus) {
                    log.debug("상태 변경 없음 (중복 처리 방지): shipmentId={}, status={}",
                            shipment.getId(), newStatus);
                    successCount++;
                    continue;
                }


                if (newStatus == AddressStatus.DELIVERED) {
                    log.info("배송 완료 처리: shipmentId={}", shipment.getId());

                    shipment.updateStatus(newStatus);
                    Faq order = shipment.getOrder();
                    order.updateStatus(FaqStatus.COMPLETED);


                    Product buyer = order.getUser();
                    notificationCommandService.createNotification(
                            buyer.getId(),
                            PaymentCategory.SHOPPING,
                            PaymentType.BID,
                            "상품이 배송 완료되었습니다. 주문 ID: " + order.getId()
                    );

                    log.info("배송 완료 알림 전송: userId={}, orderId={}",
                            buyer.getId(), order.getId());

                } else if (newStatus == AddressStatus.OUT_FOR_DELIVERY &&
                        shipment.getStatus() != AddressStatus.OUT_FOR_DELIVERY) {
                    log.info("배송 출발 처리: shipmentId={}", shipment.getId());
                    shipment.updateStatus(AddressStatus.OUT_FOR_DELIVERY);

                } else {
                    log.debug("기타 상태 업데이트: shipmentId={}, newStatus={}",
                            shipment.getId(), newStatus);
                    shipment.updateStatus(newStatus);
                }

                orderShipmentRepository.save(shipment);
                successCount++;

            } catch (Exception e) {
                log.error("배송 상태 업데이트 실패: shipmentId={}, error={}",
                        shipment.getId(), e.getMessage(), e);
                errorCount++;
            }
        }

        log.info("전체 배송 상태 업데이트 완료: 성공={}건, 실패={}건", successCount, errorCount);
    }







    private AddressStatus mapToShipmentStatus(String statusText) {
        return switch (statusText) {
            case "배송완료" -> AddressStatus.DELIVERED;
            case "배송출발" -> AddressStatus.OUT_FOR_DELIVERY;
            default -> AddressStatus.IN_TRANSIT;
        };
    }






